// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.34;

import {ContractStatus, Milestone, MilestoneInput, Transaction, UserProfile, UserRole} from "./Types.sol";

// Single on-chain entrypoint aggregating UserRegistry / AgreementFactory /
// LogisticsContract. The mutating calls here (login, register,
// createAgreement, terminateAgreement, requestCheckpoint, approveCheckpoint)
// forward on this contract's msg.sender as an explicit argument to those
// sub-contracts, which trust it because they in turn require msg.sender ==
// this contract's address (see the onlyClient modifiers on UserRegistry,
// AgreementFactory and LogisticsContract). That trusted-forwarder wiring is
// what keeps role checks like onlyShipper/onlyCarrier correct even though
// every call is routed through a single aggregator.
interface ILogisticsClient {
  function login() external view returns (UserProfile memory);

  function register(string calldata mail, string calldata name, UserRole role) external;

  // Caller sends msg.value == totalPayoutValue directly (native ETH funding).
  function createAgreement(
    address carrier,
    uint256 totalPayoutValue,
    uint256 duration,
    MilestoneInput[] calldata milestones
  ) external payable returns (address agreement);

  function listMyAgreements() external view returns (address[] memory);

  function getAgreementDetails(address agreement)
    external
    view
    returns (
      address shipper,
      address carrier,
      uint256 totalPayoutValue,
      uint256 payoutRemaining,
      uint256 duration,
      ContractStatus status,
      Milestone[] memory milestones
    );

  function terminateAgreement(address agreement) external;

  function requestCheckpoint(address agreement, uint256 milestoneIndex, uint256 checkpointIndex) external;

  function approveCheckpoint(address agreement, uint256 milestoneIndex, uint256 checkpointIndex) external;

  // currentTime: see ILogisticsContract.checkDeadlines — caller-supplied for
  // demo purposes only, forwarded as-is.
  function checkDeadlines(address agreement, uint256 currentTime) external;

  function listTransactions(address agreement) external view returns (Transaction[] memory);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.34;

import {ContractStatus, Milestone, MilestoneInput, Transaction} from "./Types.sol";

interface ILogisticsContract {
  event ContractActivated();
  event ContractTerminated();
  event ContractCompleted();
  event CheckpointRequested(uint256 indexed milestoneIndex, uint256 indexed checkpointIndex);
  event CheckpointApproved(uint256 indexed milestoneIndex, uint256 indexed checkpointIndex);
  event MilestoneStatusUpdated(uint256 indexed milestoneIndex);

  function shipper() external view returns (address);

  function carrier() external view returns (address);

  function escrow() external view returns (address);

  function totalPayoutValue() external view returns (uint256);

  function duration() external view returns (uint256);

  function payoutRemaining() external view returns (uint256);

  function status() external view returns (ContractStatus);

  function client() external view returns (address);

  function milestoneCount() external view returns (uint256);

  function getMilestone(uint256 index) external view returns (Milestone memory);

  function getTransactions() external view returns (Transaction[] memory);

  // Called once by the factory right after both this contract and its
  // paired Escrow are deployed, and again once funds have actually landed
  // in escrow (moves status from Pending -> Activated).
  function setEscrow(address escrowAddress) external;

  function activateContract() external;

  // `caller` is the real end user, forwarded by the trusted LogisticsClient
  // set at construction time - msg.sender here is always that client
  // contract, never the shipper/carrier wallet directly.
  function terminateAgreement(address caller) external;

  // Carrier flags a checkpoint as ready for review.
  function requestCheckpoint(address caller, uint256 milestoneIndex, uint256 checkpointIndex) external;

  // Shipper confirms a requested checkpoint. Once every checkpoint in a
  // milestone is approved, the milestone is marked Completed and its
  // payout share is released from escrow to the carrier.
  function approveCheckpoint(address caller, uint256 milestoneIndex, uint256 checkpointIndex) external;

  // Evaluates whether the in-progress milestone has passed its deadline
  // without completing; on failure it calls terminateAgreement() itself and
  // triggers an escrow refund to the shipper. Solidity has no native
  // scheduler, so this must be poked externally (frontend polling, or a
  // keeper bot / Chainlink Automation) — routed through the trusted
  // LogisticsClient like every other mutating call here, same as
  // terminateAgreement above.
  //
  // currentTime is caller-supplied rather than read from block.timestamp so
  // a course demo can fast-forward past a deadline without waiting real
  // time. DEMO-ONLY: a real deployment must never accept time from the
  // caller here, since it lets anyone lie about "now" to trigger an early
  // refund or dodge a failure.
  function checkDeadlines(uint256 currentTime) external;
}

